#pragma fragment frag
// target 5.0 is required by the Light Volumes cginc (Texture3D / Texture2DArray.SampleLevel).
#pragma target 5.0

#include "UnityCG.cginc"
// BoxProjectedCubemapDirection, UNITY_SPECCUBE_* and the LOD step count.
#include "UnityStandardUtils.cginc"
#include "{{LIGHT_VOLUMES_INCLUDE}}"

half _Smoothness;
half _FresnelStrength;
half _FresnelBase;
half _CorrectedReflection;
half _WorldPosFromDepth;
half _UseLightVolumes;
half _LightVolumeIntensity;
half _LightVolumeSpecular;

float3 view : TEXCOORD1;
// View-space ray with z pinned to 1. unity_CameraToWorld is +Z forward in
// shaders, so ray * eyeDepth is this pixel's view position.
float3 viewRay : TEXCOORD2;

// The clip position above is hand-built with w = 1, so clip == NDC. Invert the
// real projection to get the direction this pixel actually looks along;
// _ProjectionParams.x carries the render-target flip.
float2 ndc = float2(ssUV.x, -ssUV.y);
o.viewRay = float3(ndc.x / unity_CameraProjection._11,
                   ndc.y * _ProjectionParams.x / unity_CameraProjection._22,
                   1.0);

// Reflection probe sampling that matches the main VixForge shaders: box projection,
// probe blending across unity_SpecCube0/1, a smoothness-driven mip, and the probe's
// own HDR decode. mipBias preserves the old _ReflectionLod meaning, so at Smoothness 1
// the mip is exactly _ReflectionLod and the reflection is unchanged.
half3 VW_ProbeSpecular(float3 worldPos, float3 R, half perceptualRoughness, half mipBias)
{
    half rgh = perceptualRoughness * (1.7 - 0.7 * perceptualRoughness);
    half mip = rgh * UNITY_SPECCUBE_LOD_STEPS + mipBias;

    float3 dir0 = R;
    #ifdef UNITY_SPECCUBE_BOX_PROJECTION
        dir0 = BoxProjectedCubemapDirection(R, worldPos, unity_SpecCube0_ProbePosition, unity_SpecCube0_BoxMin, unity_SpecCube0_BoxMax);
    #endif
    half3 env = DecodeHDR(UNITY_SAMPLE_TEXCUBE_LOD(unity_SpecCube0, dir0, mip), unity_SpecCube0_HDR);

    #ifdef UNITY_SPECCUBE_BLENDING
        UNITY_BRANCH
        if (unity_SpecCube0_BoxMin.w < 0.99999)
        {
            float3 dir1 = R;
            #ifdef UNITY_SPECCUBE_BOX_PROJECTION
                dir1 = BoxProjectedCubemapDirection(R, worldPos, unity_SpecCube1_ProbePosition, unity_SpecCube1_BoxMin, unity_SpecCube1_BoxMax);
            #endif
            half3 env1 = DecodeHDR(UNITY_SAMPLE_TEXCUBE_SAMPLER_LOD(unity_SpecCube1, unity_SpecCube0, dir1, mip), unity_SpecCube1_HDR);
            env = lerp(env1, env, unity_SpecCube0_BoxMin.w);
        }
    #endif

    return env;
}

// World position for this pixel. Light Volumes and box projection both need one,
// and the pass draws a screen-space quad, so reconstruct it from the depth buffer.
float3 worldPos = _WorldSpaceCameraPos;
if (_WorldPosFromDepth > 0.5)
{
    float2 depthUV = i.uv;
    depthUV.y = -depthUV.y * _ProjectionParams.x + step(0, _ProjectionParams.x);
    depthUV = UnityStereoScreenSpaceUVAdjust(depthUV, _CameraDepthTexture_ST);
    // The asset declares _CameraDepthTexture as a sampler2D, so read it directly.
    // SAMPLE_DEPTH_TEXTURE expands to a Texture2DArray sampler under
    // STEREO_INSTANCING_ON and needs sampler_CameraDepthTexture, which does not exist here.
    float eyeDepth = LinearEyeDepth(tex2D(_CameraDepthTexture, depthUV).r);
    eyeDepth = clamp(eyeDepth, _ProjectionParams.y, _ProjectionParams.z);
    worldPos = mul(unity_CameraToWorld, float4(i.viewRay * eyeDepth, 1.0)).xyz;
}

// The height-field normal is built in a screen-space basis, so its facing is not
// guaranteed. Force it towards the viewer before anything takes an N.V from it.
float3 viewRayW = normalize(mul((float3x3)unity_CameraToWorld, i.viewRay));
float3 V = -viewRayW;
float3 N = dot(normal, V) < 0.0 ? -normal : normal;
half NdotV = saturate(dot(N, V));

// GI/ambient lighting
half3 lightColor = ShadeSH9(half4(N, 1)) + UNITY_LIGHTMODEL_AMBIENT;

// Dielectric F0 for a liquid, tinted towards the liquid colour as metallic rises.
half3 f0 = lerp(half3(_FresnelBase, _FresnelBase, _FresnelBase), baseColor, _Metallic);

half3 lvSpec = 0;
UNITY_BRANCH
if (_UseLightVolumes > 0.5 && LightVolumesEnabled() > 0.5)
{
    float3 L0, L1r, L1g, L1b;
    LightVolumeSH(worldPos, L0, L1r, L1g, L1b, float3(0, 0, 0), N);

    // Blend towards the volume so intensity 0 still leaves the probe ambient.
    half3 lvDiffuse = max(0.0, LightVolumeEvaluate(N, L0, L1r, L1g, L1b));
    lightColor = lerp(lightColor, lvDiffuse * _LightVolumeIntensity, saturate(_LightVolumeIntensity));
    lvSpec = max(0.0, LightVolumeSpecular(f0, _Smoothness, N, V, L0, L1r, L1g, L1b))
           * (_LightVolumeIntensity * _LightVolumeSpecular);
}

// Reflections. The legacy vector inverted screen-space x, which mirrored the
// reflection horizontally and ignored the render-target flip; the corrected one is
// rebuilt from the real projection. Set Corrected Reflection Vector to 0 for the old look.
float3 incident = _CorrectedReflection > 0.5 ? viewRayW : i.view;
float3 reflectionVector = reflect(incident, N);

skyColor += lvSpec;

// Grazing angles reflect more than head-on ones. Fresnel 0 restores the flat response.
half fresnel = pow(1.0 - NdotV, 5.0);
half reflWeight = lerp(1.0, lerp(_FresnelBase, 1.0, fresnel), _FresnelStrength);
half reflStrength = _ReflectionStrength * reflWeight;
